import{_ as t,o,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Bitbucket","description":"","frontmatter":{},"headers":[],"relativePath":"guide/bitbucket.md","filePath":"guide/bitbucket.md"}'),r={name:"guide/bitbucket.md"};function n(a,e,c,l,h,d){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="bitbucket" tabindex="-1">Bitbucket <a class="header-anchor" href="#bitbucket" aria-label="Permalink to &quot;Bitbucket&quot;">​</a></h1><p>Orbit builds and deploys from Bitbucket Cloud, with deploy on push and pull request previews, the same way it does from <a href="./github">GitHub</a>. Bitbucket Data Center is not supported.</p><h2 id="connecting" tabindex="-1">Connecting Bitbucket <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting Bitbucket {#connecting}&quot;">​</a></h2><p>In <strong>Settings → Integrations → Connect Bitbucket</strong>, or when you pick Bitbucket in a new project, give Orbit:</p><ul><li><strong>The workspace ID</strong>, as in <code>https://bitbucket.org/&lt;workspace&gt;/</code>.</li><li><strong>An access token</strong> from that workspace: a workspace access token reaches all its repositories, a project access token those of one project, and a repository access token a single repository. Give it these permissions: <ul><li><strong>Repositories: Read</strong>, to list and read the repositories and clone them for builds;</li><li><strong>Webhooks: Read and write</strong>, to add the webhooks that deploy on push;</li><li><strong>Pull requests: Read</strong>, optional, so pull requests reach Orbit and get previews.</li></ul></li></ul><p>A token without the first two is refused with a message that names the missing scope. Without the third, pushes deploy but pull requests get no preview; Settings says so.</p><ul><li><strong>Where the token lives:</strong> it is sealed in Orbit&#39;s secret store, never shown again and never written to the logs. It travels with <code>orbit backup</code>.</li><li><strong>Each workspace</strong> in Orbit connects its own Bitbucket workspace.</li></ul><h2 id="repositories" tabindex="-1">Choosing a repository <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Choosing a repository {#repositories}&quot;">​</a></h2><p>In a new project, choose <strong>Git repository</strong>, then <strong>Bitbucket</strong>. Orbit lists the repositories the token can read, most recently updated first. Pick one and a branch, and Orbit reads the branch through Bitbucket&#39;s API to detect how to build and run it, as it does for GitHub. The Compose import also reads a <code>compose.yaml</code> from a Bitbucket repository.</p><p><strong>Builds clone with git.</strong> Bitbucket does not let access tokens download a commit&#39;s archive, so Orbit fetches the commit with <code>git</code> on the main server, authenticated with the token. Ubuntu Server ships <code>git</code>; on a server without it, install it (<code>apt-get install git</code>) before deploying from Bitbucket, or the build fails saying so.</p><h2 id="push" tabindex="-1">Deploying on push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;Deploying on push {#push}&quot;">​</a></h2><p>When an application is created from a Bitbucket repository, Orbit adds a webhook to that repository. It sends pushes, and pull requests when the token can read them, to <code>https://orbit.&lt;server-ip-with-dashes&gt;.sslip.io/bitbucket/webhook/&lt;workspace&gt;</code>, signed with a secret only your server knows (<code>X-Hub-Signature</code>).</p><ul><li>A delivery without a signature, or with a wrong one, is refused.</li><li>A push to an application&#39;s branch deploys that commit when <strong>Deploy automatically</strong> is on in the application&#39;s settings.</li><li>The same delivery sent twice deploys once.</li><li>Settings → Integrations lists each repository&#39;s webhook, or why it could not be added.</li></ul><h2 id="previews" tabindex="-1">Pull request previews <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Pull request previews {#previews}&quot;">​</a></h2><p>Previews follow the <a href="./github#previews">same rules as on GitHub</a>: turn them on in a project&#39;s <strong>Previews</strong>, and every pull request opened from a branch of a repository that the source environment builds gets a preview, redeployed on every push and removed with its data when the pull request is merged or declined.</p><ul><li><strong>Forks:</strong> pull requests from forks never get a preview, so code from outside the repository never runs on your servers.</li></ul><h2 id="disconnecting" tabindex="-1">Disconnecting <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;Disconnecting {#disconnecting}&quot;">​</a></h2><p><strong>Disconnect Bitbucket</strong> removes the webhooks Orbit added and forgets the token. Applications keep their source and can be connected again later, but they stop deploying on push.</p>',18)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
